SELECT a.COMB_SYMBOL AS `股票代码`, a.CSNAME AS `股票名称`, ROUND((v.CLOSE_PRICE * v.TOTAL_SHARES) / 100000000, 1) AS `总市值(亿美元)` FROM VIEW_US_EOD_EXPR v JOIN AMERICAN_STOCK_MAIN a ON v.FIU_ID = a.FIU_ID WHERE v.TRADE_DATE = (SELECT MAX(TRADE_DATE) FROM VIEW_US_EOD_EXPR WHERE TRADE_DATE IS NOT NULL) AND a.IS_CHINESE_STOCK = '中概股' AND v.CLOSE_PRICE IS NOT NULL AND v.TOTAL_SHARES IS NOT NULL ORDER BY (v.CLOSE_PRICE * v.TOTAL_SHARES) DESC LIMIT 3;
